"""
Web font CSS for Platform Atlas HTML reports.

get_font_css() returns either the Google Fonts @import (network_policy=allow,
the default) or inline base64-encoded woff2 data URIs (network_policy=disallow).

Three families, each with a job in the report's type system:

    Newsreader      --font-display  headlines, section titles, big numerals
    Hanken Grotesk  --font-ui/body  prose plus the small uppercase labels
    JetBrains Mono  --font-mono     rule ids, paths, captured values

Latin + latin-ext subsets only; all three are variable-weight files, so one
@font-face per subset covers each family's full weight range (~250 KB embedded).
Every face carries its unicode-range: without one the latin block shadows
latin-ext for the whole family, dropping accented glyphs out of the embedded
font entirely.

The display stack in the templates is:

    var(--font-local-display, "Iowan Old Style"), "Newsreader", Georgia, serif

so macOS readers get the locally installed Iowan Old Style, which Newsreader was
chosen to sit beside. Offline reports must not depend on a font that merely
happens to be installed, so the embedded branch also emits --font-local-display
and every reader gets the bundled Newsreader instead.
"""

_GOOGLE_FONTS_IMPORT = (
    "@import url('https://fonts.googleapis.com/css2?"
    "family=Hanken+Grotesk:wght@300..800"
    "&family=Newsreader:wght@200..800"
    "&family=JetBrains+Mono:wght@400..600"
    "&display=swap');"
)

# Pins the display face to the embedded Newsreader so an air-gapped report
# renders identically everywhere instead of varying with what macOS ships.
_OFFLINE_DISPLAY_PIN = ":root{--font-local-display:'Newsreader';}"

_EMBEDDED_FACES = """
/* latin-ext */
@font-face {
  font-family: 'Newsreader';
  font-style: normal;
  font-weight: 200 800;
  font-display: swap;
  src: url(data:font/woff2;base64,) format('woff2');
  unicode-range: U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C0, U+2113, U+2C60-2C7F, U+A720-A7FF;
}
/* latin */
@font-face {
  font-family: 'Newsreader';
  font-style: normal;
  font-weight: 200 800;
  font-display: swap;
  src: url(data:font/woff2;base64,) format('woff2');
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}
/* latin-ext */
@font-face {
  font-family: 'Hanken Grotesk';
  font-style: normal;
  font-weight: 300 800;
  font-display: swap;
  src: url(data:font/woff2;base64,) format('woff2');
  unicode-range: U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C0, U+2113, U+2C60-2C7F, U+A720-A7FF;
}
/* latin */
@font-face {
  font-family: 'Hanken Grotesk';
  font-style: normal;
  font-weight: 300 800;
  font-display: swap;
  src: url(data:font/woff2;base64,) format('woff2');
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}
/* latin-ext */
@font-face {
  font-family: 'JetBrains Mono';
  font-style: normal;
  font-weight: 400 600;
  font-display: swap;
  src: url(data:font/woff2;base64,) format('woff2');
  unicode-range: U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C0, U+2113, U+2C60-2C7F, U+A720-A7FF;
}
/* latin */
@font-face {
  font-family: 'JetBrains Mono';
  font-style: normal;
  font-weight: 400 600;
  font-display: swap;
  src: url(data:font/woff2;base64,) format('woff2');
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}
"""

EMBEDDED_FONTS_CSS = _EMBEDDED_FACES + _OFFLINE_DISPLAY_PIN


def get_font_css() -> str:
    """Return font CSS for the active network_policy.

    allow (default): Google Fonts CDN @import — browsers fetch only what
    they need. disallow: self-contained base64 woff2 data URIs with no
    outbound browser requests, plus the display-face pin above.
    """
    try:
        from platform_atlas.core.config import is_config_loaded, get_config
        if is_config_loaded() and get_config().network_policy == "disallow":
            return EMBEDDED_FONTS_CSS
    except Exception:
        pass
    return _GOOGLE_FONTS_IMPORT
